test('actionable element setup for /empty did not discover any interactive elements', async ({ page }) => {
  await page.goto('/empty');
  await page.waitForLoadState('domcontentloaded');

  const elements = await page.locator('a[href], button, input:not([type="hidden"]), select, textarea, form, [role="button"]').evaluateAll((nodes) => {
    return Array.from(nodes)
      .map((node) => ({
        text: node.textContent?.replace(/s+/g, ' ').trim() ?? '',
        role: node.getAttribute('role') ?? '',
        id: node.getAttribute('id') ?? '',
        tagName: node.tagName.toLowerCase(),
      }))
      .filter((element) => Boolean(element.text || element.role || element.id));
  });

  expect(
    elements.length,
    'No actionable elements were discovered during introspection, so classified interaction results could not be generated.'
  ).toBeGreaterThan(0);
});

buildToggleGroupTests:
test('toggle group "Formatting toolbar" (2 members) exposes ARIA state on every member', async ({ page }) => {
  await page.goto('/');
  await page.waitForLoadState('domcontentloaded');

  {
    const locator = page.locator('[id="bold-btn"]').first();
    const [pressed, selected, checked, expanded] = await Promise.all([
      locator.getAttribute('aria-pressed'),
      locator.getAttribute('aria-selected'),
      locator.getAttribute('aria-checked'),
      locator.getAttribute('aria-expanded'),
    ]);
    expect(
      pressed !== null || selected !== null || checked !== null || expanded !== null,
      'Bold is part of a detected toggle/selection group but exposes no ARIA state attribute (aria-pressed/aria-selected/aria-checked/aria-expanded), so assistive technology has no way to tell which member is current'
    ).toBeTruthy();
  }

  {
    const locator = page.locator('[id="italic-btn"]').first();
    const [pressed, selected, checked, expanded] = await Promise.all([
      locator.getAttribute('aria-pressed'),
      locator.getAttribute('aria-selected'),
      locator.getAttribute('aria-checked'),
      locator.getAttribute('aria-expanded'),
    ]);
    expect(
      pressed !== null || selected !== null || checked !== null || expanded !== null,
      'Italic is part of a detected toggle/selection group but exposes no ARIA state attribute (aria-pressed/aria-selected/aria-checked/aria-expanded), so assistive technology has no way to tell which member is current'
    ).toBeTruthy();
  }
});

test('toggle group "Formatting toolbar": clicking a member flips its aria-pressed, and the previously-active member reverts', async ({ page }) => {
  await page.goto('/');
  await page.waitForLoadState('domcontentloaded');

  const active = page.locator('[id="bold-btn"]').first(); // Bold, active at introspection time
  const target = page.locator('[id="italic-btn"]').first(); // Italic, inactive at introspection time

  await target.click();

  const activeAfter = await active.getAttribute('aria-pressed');
  const targetAfter = await target.getAttribute('aria-pressed');

  expect(targetAfter, 'Italic should report an active aria-pressed after being clicked').toBe('true');
  expect(activeAfter, 'Bold should no longer report an active aria-pressed once a sibling is selected').not.toBe('true');
});

