buildAccessibilityElementTests:
test('accessible name and role: Fetch status [link]', async ({ page }) => {
  await page.goto('/');
  await page.waitForLoadState('domcontentloaded');

  const locator = page.locator('[id="status-link"]').first();
  // HTML-AAM 4.1.10: an <img alt=""> is presentational and has no name; its title counts only when there is no alt.
  // Playwright falls back to that title, so it is taken off before the name is read (the page is not reused).
  const presentationalTitles = await locator.evaluate((element) => Array.from(element.querySelectorAll('img[alt=""][title]')).map((image) => {
    const title = image.getAttribute('title') ?? '';
    image.removeAttribute('title');
    return title;
  }));
  await expect(locator, presentationalTitles.length > 0
    ? 'Fetch status has no accessible name: HTML-AAM 4.1.10 gives an <img alt=""> no name and does not use its title ("' + presentationalTitles.join('", "') + '")'
    : 'Fetch status has no accessible name in the accessibility tree').toHaveAccessibleName(/.+/);

  const ariaSnapshot = (await locator.ariaSnapshot()).trim();
  const role = ariaSnapshot.match(/^-\s*(\S+)/)?.[1];
  expect(role, 'Fetch status has no discoverable role in its aria snapshot: ' + ariaSnapshot).toBeTruthy();
});

