test('action pair: Undo / Redo are unaffected by an unrelated interaction', async ({ page }) => {
  await page.goto('/');
  await page.waitForLoadState('domcontentloaded');

  const elementA = page.locator('[id="undo-btn"]').first();
  const elementB = page.locator('[id="redo-btn"]').first();
  const before = {
    aEnabled: await elementA.isEnabled(),
    aText: (await elementA.textContent())?.trim() ?? '',
    bEnabled: await elementB.isEnabled(),
    bText: (await elementB.textContent())?.trim() ?? '',
  };

  // Unrelated no-op: a mouse move to a neutral point has nothing to do
  // with the Undo/Redo pair, so it should never change either
  // element's state.
  await page.mouse.move(0, 0);

  const after = {
    aEnabled: await elementA.isEnabled(),
    aText: (await elementA.textContent())?.trim() ?? '',
    bEnabled: await elementB.isEnabled(),
    bText: (await elementB.textContent())?.trim() ?? '',
  };

  expect(after.aEnabled, 'Undo enabled state changed after an unrelated interaction').toBe(before.aEnabled);
  expect(after.aText, 'Undo text changed after an unrelated interaction').toBe(before.aText);
  expect(after.bEnabled, 'Redo enabled state changed after an unrelated interaction').toBe(before.bEnabled);
  expect(after.bText, 'Redo text changed after an unrelated interaction').toBe(before.bText);
});
